using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using NUnit.Framework;

namespace xpTURN.Feedback.Tests.Motion
{
    // the shape fingerprint — fixed samples of every kernel against committed constants (relative 10⁻⁵, absolute below 1;
    // integer results exact). Property tests cannot see a changed shape. An intended change rewrites the constants in the
    // same commit — WriteFingerprint prints them
    public sealed class ShapeFingerprintTests
    {
        static readonly (float Vibrato, float Decay)[] Punches = { (5f, 1f), (3f, 0.5f), (2.25f, 2f) };
        static readonly float[] Zetas = { 0.05f, 0.4f, 1f, 1.5f, 10f };

        static double[] Range(int count, Func<int, double> sample) => Enumerable.Range(0, count).Select(sample).ToArray();

        static IEnumerable<(string Name, bool Exact, double[] Values)> Samples()
        {
            foreach (var e in EasingTests.Curves)
                yield return ($"Ease.{e}", false, Range(9, i => Easing.Evaluate(e, EasingTests.P1(e), EasingTests.P2(e), i / 8f)));
            foreach (var (vibrato, decay) in Punches)
                yield return (FormattableString.Invariant($"Punch.{vibrato}_{decay}"), false, Range(9, i => MotionKernels.Punch(i / 8f, vibrato, decay)));
            foreach (Waveform w in Enum.GetValues(typeof(Waveform)))
                yield return ($"Wave.{w}", false, Range(10, i => MotionKernels.Wave(w, i * 0.13)));
            yield return ("Warp.3yoyo", false, Range(9, i => MotionKernels.Warp(i / 8f, 3, true)));
            yield return ("Warp.2", false, Range(9, i => MotionKernels.Warp(i / 8f, 2, false)));
            yield return ("Trapezoid", false, Range(22, i => MotionKernels.Trapezoid(i % 11 / 10f, i < 11 ? 0.2f : 0.6f, i < 11 ? 0.3f : 0.6f, i < 11 ? 0.2f : 0.6f, out _)));
            yield return ("TrapezoidRamp", true, Range(22, i =>
            {
                MotionKernels.Trapezoid(i % 11 / 10f, i < 11 ? 0.2f : 0.6f, i < 11 ? 0.3f : 0.6f, i < 11 ? 0.2f : 0.6f, out bool ramp);
                return ramp ? 1 : 0;
            }));
            yield return ("Blink.StartOn", true, Range(64, i => MotionKernels.Blink(3u, i * 0.013, 0.1f, 0.3f, 0.5f, true) ? 1 : 0));
            yield return ("Blink.StartOff", true, Range(64, i => MotionKernels.Blink(3u, i * 0.013, 0.1f, 0.3f, 0.5f, false) ? 1 : 0));
            yield return ("Smooth", false, Range(16, i => Noise.Smooth(7u, i * 0.37)));
            yield return ("Smooth.3e9", false, Range(16, i => Noise.Smooth(7u, 3e9 + i * 0.37)));
            yield return ("SmoothHz", false, Range(16, i => Noise.SmoothHz(5u, 10f, i * 0.011)));
            yield return ("Jitter", false, Range(16, i => Noise.Jitter(7u, 3f, i * 0.1)));
            yield return ("Jitter.3e9", false, Range(16, i => Noise.Jitter(7u, 3f, 1e9 + i * 0.1)));
            for (int octaves = 1; octaves <= 3; octaves++)
            {
                int o = octaves;
                yield return ($"Fbm.{o}", false, Range(16, i => Noise.Fbm(7u, 2f, i * 0.07, o)));
            }
            yield return ("Fbm.3e9", false, Range(16, i => Noise.Fbm(7u, 3f, 1e9 + i * 0.07, 3)));
            foreach (float zeta in Zetas)
            {
                var shape = SpringShape.Of(6f, zeta);
                string z = zeta.ToString(CultureInfo.InvariantCulture);
                yield return ($"Y.MoveTo.{z}", false, Range(16, i => SpringMath.Y(shape, 1f, 0f, i * 0.02f)));
                yield return ($"Y.Bump.{z}", false, Range(16, i => SpringMath.Y(shape, 0f, shape.Omega0, i * 0.02f)));
                var m = SpringMath.Step(shape, 1f / 60f);
                yield return ($"Step.{z}", false, new double[] { m.A11, m.A12, m.A21, m.A22 });
                yield return ($"SettleTime.{z}", false, Range(4, i => SpringMath.SettleTime(shape, i < 2 ? 1e-3f : 0.2f, (i & 1) == 0)));
            }
        }

        [Test]
        public void KernelsKeepTheirCommittedShape()
        {
            var samples = Samples().ToArray();
            Assert.That(Committed.Keys.OrderBy(k => k, StringComparer.Ordinal), Is.EqualTo(samples.Select(s => s.Name).OrderBy(k => k, StringComparer.Ordinal)), "sample names");
            foreach (var (name, exact, values) in samples)
            {
                double[] expected = Committed[name];
                Assert.That(values.Length, Is.EqualTo(expected.Length), name);
                for (int i = 0; i < values.Length; i++)
                {
                    double tolerance = exact ? 0.0 : 1e-5 * Math.Max(1.0, Math.Abs(expected[i]));
                    Assert.That(values[i], Is.EqualTo(expected[i]).Within(tolerance), $"{name}[{i}]");
                }
            }
        }

        [Test, Explicit("prints the committed constants — run by hand for an intended shape change")]
        public void WriteFingerprint()
        {
            var text = new StringBuilder();
            foreach (var (name, _, values) in Samples())
                text.Append("            [\"").Append(name).Append("\"] = new double[] { ")
                    .Append(string.Join(", ", values.Select(v => v.ToString("R", CultureInfo.InvariantCulture))))
                    .AppendLine(" },");
            string path = Path.Combine(TestContext.CurrentContext.WorkDirectory, "ShapeFingerprint.txt");
            File.WriteAllText(path, text.ToString());
            TestContext.WriteLine(path);
        }

